import json, sys, zlib


def u16(b, o):
    return b[o] | (b[o + 1] << 8)


def u32(b, o):
    return b[o] | (b[o + 1] << 8) | (b[o + 2] << 16) | (b[o + 3] << 24)


def solve(req):
    pages = [bytes.fromhex(p) for p in req["pages"]]
    try:
        log = bytes.fromhex(req.get("log") or "")
    except ValueError:
        log = b""
    ckpt = req.get("checkpoint", 0)
    if not isinstance(ckpt, int) or ckpt < 0:
        ckpt = 0

    npages = len(pages)
    plens = [len(p) for p in pages]
    out = [bytearray(p) for p in pages]

    active = {}          # txid -> list of staged PATCH payload bytes
    pos = 0
    n = len(log)
    last_seq = 0

    while pos + 13 <= n:
        plen = u32(log, pos)
        seq = u32(log, pos + 4)
        kind = log[pos + 8]
        tid = u32(log, pos + 9)
        end = pos + 13 + plen + 4
        if plen > 4096 or end > n:
            break
        payload = log[pos + 13:pos + 13 + plen]
        crc = u32(log, end - 4)
        if zlib.crc32(log[pos:pos + 13 + plen]) & 0xFFFFFFFF != crc:
            break
        if seq <= 0 or seq <= last_seq:
            break
        if tid <= 0:
            break

        if kind == 1 or kind == 4:          # BEGIN / ABORT: empty payload
            if plen != 0:
                break
        elif kind == 2:                     # PATCH
            if plen < 6:
                break
            cnt = u16(payload, 4)
            if cnt == 0 or plen != 6 + cnt:
                break
            pi = u16(payload, 0)
            off = u16(payload, 2)
            if pi >= npages or off + cnt > plens[pi]:
                break
        elif kind == 3:                     # COMMIT
            if plen != 8:
                break
        else:
            break

        # Structurally valid: apply semantics.
        if kind == 1:
            active[tid] = []
        elif kind == 2:
            st = active.get(tid)
            if st is not None:
                st.append(payload)
        elif kind == 4:
            active.pop(tid, None)
        else:                               # COMMIT
            staged = active.pop(tid, None)
            if staged is not None:
                pc = u32(payload, 0)
                dg = u32(payload, 4)
                if (pc == len(staged)
                        and dg == (zlib.crc32(b"".join(staged)) & 0xFFFFFFFF)
                        and seq > ckpt):
                    for p in staged:
                        pi = u16(p, 0)
                        off = u16(p, 2)
                        cnt = u16(p, 4)
                        out[pi][off:off + cnt] = p[6:6 + cnt]

        last_seq = seq
        pos = end

    return {
        "pages": [b.hex() for b in out],
        "valid_bytes": pos,
        "last_seq": last_seq,
    }


if __name__ == "__main__":
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.write(json.dumps(solve(json.loads(line))) + "\n")
    out.flush()
